'use client'

import {
  cloneElement,
  createContext,
  forwardRef,
  isValidElement,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  type HTMLAttributes,
  type ReactNode,
} from 'react'
import { Slot } from '@radix-ui/react-slot'
import { motion, useMotionValue, useReducedMotion, useSpring, type MotionValue } from 'motion/react'
import { cn } from '@/lib/utils'
import { springs } from '@/lib/motion-tokens'
import {
  useProximityHighlight,
  ProximityHighlight,
  type ItemRect,
} from '@/lib/hooks/use-proximity-highlight'
import { WeightShiftText } from '@/components/ui/weight-shift-text'

interface NavMenuContextValue {
  activeSlug: string | null
  nextIndex: () => number
  registerItem: (index: number, el: HTMLElement | null) => void
}

const NavMenuContext = createContext<NavMenuContextValue | null>(null)

function useNavMenuCtx(componentName: string) {
  const ctx = useContext(NavMenuContext)
  if (!ctx) throw new Error(`${componentName} must be used within NavMenu`)
  return ctx
}

interface NavMenuContentContextValue {
  activeIndex: number | null
  setActiveIndex: (i: number | null) => void
  highlightX: ReturnType<typeof import('motion/react').useSpring>
  highlightSize: MotionValue<number>
  highlightOpacity: ReturnType<typeof import('motion/react').useSpring>
  axis: 'x' | 'y'
  registerItem: (index: number, el: HTMLElement | null) => void
}

const NavMenuContentContext = createContext<NavMenuContentContextValue | null>(null)

function useNavMenuContentCtx(componentName: string) {
  const ctx = useContext(NavMenuContentContext)
  if (!ctx) throw new Error(`${componentName} must be used within NavMenuContent`)
  return ctx
}

export interface NavMenuProps extends HTMLAttributes<HTMLElement> {
  children: ReactNode
  activeSlug: string | null
  'aria-label'?: string
}

export const NavMenu = forwardRef<HTMLElement, NavMenuProps>(
  ({ children, activeSlug, 'aria-label': ariaLabel = 'Main', className, ...props }, ref) => {
    const navRef = useRef<HTMLElement>(null)
    const activeItemRectRef = useRef<ItemRect | null>(null)

    const {
      activeIndex,
      setActiveIndex,
      registerItem,
      handlers,
      highlightX,
      highlightSize,
      highlightOpacity,
      axis,
    } = useProximityHighlight(navRef, { axis: 'y' })

    const indexRef = useRef(0)
    const nextIndex = useCallback(() => {
      const idx = indexRef.current
      indexRef.current += 1
      return idx
    }, [])

    const rawActiveX = useMotionValue(0)
    const rawActiveSize = useMotionValue(0)
    const rawActiveOpacity = useMotionValue(0)
    const reduceMotion = useReducedMotion()
    const activeSpringOpts = reduceMotion ? { duration: 0 } : springs.moderate
    const activeX = useSpring(rawActiveX, activeSpringOpts)
    const activeSize = useSpring(rawActiveSize, activeSpringOpts)
    const activeOpacity = useSpring(rawActiveOpacity, activeSpringOpts)

    const isHoveringOther = activeIndex !== null

    useEffect(() => {
      if (!activeItemRectRef.current) return
      if (reduceMotion) {
        rawActiveOpacity.jump(isHoveringOther ? 0.8 : 1)
      } else {
        rawActiveOpacity.set(isHoveringOther ? 0.8 : 1)
      }
    }, [isHoveringOther, reduceMotion, rawActiveOpacity])

    useEffect(() => {
      const nav = navRef.current
      if (!nav) return
      const items = Array.from(nav.querySelectorAll<HTMLElement>('[data-nav-item]'))
      const found = items.find((el) => el.getAttribute('data-slug') === activeSlug)
      if (found) {
        const rect: ItemRect = {
          top: found.offsetTop,
          height: found.offsetHeight,
          left: found.offsetLeft,
          width: found.offsetWidth,
        }
        activeItemRectRef.current = rect
        if (reduceMotion) {
          rawActiveX.jump(rect.top)
          rawActiveSize.jump(rect.height)
          rawActiveOpacity.jump(1)
        } else {
          rawActiveX.set(rect.top)
          rawActiveSize.jump(rect.height)
          rawActiveOpacity.set(1)
        }
      } else {
        activeItemRectRef.current = null
        if (reduceMotion) rawActiveOpacity.jump(0)
        else rawActiveOpacity.set(0)
      }
    }, [activeSlug, reduceMotion, rawActiveX, rawActiveSize, rawActiveOpacity])

    useEffect(() => {
      const nav = navRef.current
      if (!nav) return
      const handleKeyDown = (e: KeyboardEvent) => {
        if (!nav.contains(document.activeElement)) return
        const items = nav.querySelectorAll<HTMLElement>('[data-nav-item]:not([data-disabled])')
        if (!items.length) return
        const count = items.length
        const currentIdx = Array.from(items).indexOf(document.activeElement as HTMLElement)

        if (e.key === 'ArrowDown') {
          e.preventDefault()
          const next = currentIdx < 0 ? 0 : (currentIdx + 1) % count
          items[next]?.focus()
        } else if (e.key === 'ArrowUp') {
          e.preventDefault()
          const next = currentIdx < 0 ? count - 1 : (currentIdx - 1 + count) % count
          items[next]?.focus()
        } else if (e.key === 'Home') {
          e.preventDefault()
          items[0]?.focus()
        } else if (e.key === 'End') {
          e.preventDefault()
          items[count - 1]?.focus()
        }
      }
      document.addEventListener('keydown', handleKeyDown)
      return () => document.removeEventListener('keydown', handleKeyDown)
    }, [])

    const setRefs = useCallback(
      (node: HTMLElement | null) => {
        ;(navRef as React.MutableRefObject<HTMLElement | null>).current = node
        if (typeof ref === 'function') ref(node)
        else if (ref) (ref as React.MutableRefObject<HTMLElement | null>).current = node
      },
      [ref],
    )

    const contentCtx = useMemo<NavMenuContentContextValue>(
      () => ({
        activeIndex,
        setActiveIndex,
        highlightX,
        highlightSize,
        highlightOpacity,
        axis,
        registerItem,
      }),
      [
        activeIndex,
        setActiveIndex,
        highlightX,
        highlightSize,
        highlightOpacity,
        axis,
        registerItem,
      ],
    )

    return (
      <NavMenuContext.Provider value={{ activeSlug, nextIndex, registerItem }}>
        <NavMenuContentContext.Provider value={contentCtx}>
          <nav
            ref={setRefs}
            aria-label={ariaLabel}
            className={cn('relative flex flex-col gap-0.5', className)}
            {...handlers}
            {...props}
          >
            <motion.div
              aria-hidden="true"
              className="pointer-events-none absolute inset-x-1 rounded-md squircle-corners bg-(--color-accent)/12"
              style={{ y: activeX, height: activeSize, opacity: activeOpacity }}
            />
            <ProximityHighlight
              highlightX={highlightX}
              highlightSize={highlightSize}
              highlightOpacity={highlightOpacity}
              axis={axis}
              className="mx-1 rounded-md squircle-corners bg-(--color-fg)/8"
            />
            {children}
          </nav>
        </NavMenuContentContext.Provider>
      </NavMenuContext.Provider>
    )
  },
)
NavMenu.displayName = 'NavMenu'

export interface NavMenuItemProps extends HTMLAttributes<HTMLAnchorElement> {
  href: string
  label: string
  icon?: ReactNode
  isNew?: boolean
  isUpdated?: boolean
  asChild?: boolean
}

export const NavMenuItem = forwardRef<HTMLAnchorElement, NavMenuItemProps>(
  (
    { href, label, icon, isNew, isUpdated, asChild = false, className, children, ...props },
    ref,
  ) => {
    const { activeSlug, nextIndex } = useNavMenuCtx('NavMenuItem')
    const { activeIndex, setActiveIndex, registerItem } = useNavMenuContentCtx('NavMenuItem')

    const itemRef = useRef<HTMLAnchorElement | null>(null)
    const indexRef = useRef<number | null>(null)
    if (indexRef.current === null) indexRef.current = nextIndex()
    // eslint-disable-next-line react-hooks/refs
    const index = indexRef.current
    const isActive = activeSlug === href
    const isHovered = activeIndex === index

    useEffect(() => {
      const el = itemRef.current
      if (index < 0 || !el) return
      registerItem(index, el)
      return () => registerItem(index, null)
    }, [index, registerItem])

    const setItemRef = useCallback(
      (node: HTMLAnchorElement | null) => {
        itemRef.current = node
        if (typeof ref === 'function') ref(node)
        else if (ref) (ref as React.MutableRefObject<HTMLAnchorElement | null>).current = node
      },
      [ref],
    )

    const weight = isActive ? 550 : isHovered ? 500 : 400

    const itemClassName = cn(
      'group relative flex min-h-11 items-center gap-2.5 rounded-md squircle-corners px-3 py-2 text-sm outline-none transition-colors duration-(--motion-dur-fast) motion-reduce:transition-none',
      'text-(--color-muted) hover:text-(--color-fg)',
      'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent) focus-visible:ring-offset-2 focus-visible:ring-offset-(--color-bg)',
      isActive && 'text-(--color-fg)',
      className,
    )

    const sharedProps = {
      'data-nav-item': true,
      'data-slug': href,
      'aria-current': isActive ? ('page' as const) : undefined,
      tabIndex: isActive ? 0 : -1,
      onFocus: () => setActiveIndex(index),
    }

    const content = (
      <>
        {icon && (
          <span className="shrink-0 [&_svg]:size-4" aria-hidden="true">
            {icon}
          </span>
        )}
        <WeightShiftText
          baseWeight={400}
          activeWeight={weight}
          active={isActive || isHovered}
          duration="150ms"
          className="min-w-0"
        >
          {label}
        </WeightShiftText>
        {isNew && (
          <>
            <span
              className="size-1.5 shrink-0 rounded-full bg-(--color-accent)"
              aria-hidden="true"
            />
            <span className="sr-only">New</span>
          </>
        )}
        {isUpdated && !isNew && (
          <>
            <span
              className="size-1.5 shrink-0 rounded-full bg-(--color-subtle)"
              aria-hidden="true"
            />
            <span className="sr-only">Updated</span>
          </>
        )}
      </>
    )

    if (asChild && isValidElement(children)) {
      return (
        <Slot ref={setItemRef} className={itemClassName} {...sharedProps} {...props}>
          {cloneElement(children as React.ReactElement, undefined, content)}
        </Slot>
      )
    }

    return (
      <a ref={setItemRef} href={href} className={itemClassName} {...sharedProps} {...props}>
        {content}
      </a>
    )
  },
)
NavMenuItem.displayName = 'NavMenuItem'

export function NavMenuPreview() {
  return (
    <div
      className="flex h-full w-full items-center justify-center p-6"
      style={{ backgroundColor: 'var(--color-surface)' }}
    >
      <div className="w-48">
        <NavMenu activeSlug="/docs/install" aria-label="Docs">
          <NavMenuItem href="/docs" label="Overview" />
          <NavMenuItem href="/docs/install" label="Install" isNew />
          <NavMenuItem href="/docs/theming" label="Theming" />
          <NavMenuItem href="/docs/components" label="Components" isUpdated />
        </NavMenu>
      </div>
    </div>
  )
}

'use client'

import { forwardRef, useState, type HTMLAttributes, type ReactNode } from 'react'
import { useReducedMotion } from 'motion/react'
import { cn } from '@/lib/utils'
import { durations } from '@/lib/motion-tokens'

export interface WeightShiftTextProps extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'> {
  children: ReactNode
  baseWeight?: number
  activeWeight?: number
  active?: boolean
  duration?: string
}

export const WeightShiftText = forwardRef<HTMLSpanElement, WeightShiftTextProps>(
  (
    {
      children,
      baseWeight = 400,
      activeWeight = 600,
      active,
      duration = durations.fast,
      className,
      style,
      onMouseEnter: onMouseEnterProp,
      onMouseLeave: onMouseLeaveProp,
      ...props
    },
    ref,
  ) => {
    const reduceMotion = useReducedMotion()
    const [isHovered, setIsHovered] = useState(false)

    const isControlledActive = active !== undefined
    const currentWeight = isControlledActive
      ? active
        ? activeWeight
        : baseWeight
      : isHovered
        ? activeWeight
        : baseWeight

    return (
      <span
        ref={ref}
        className={cn('relative inline-block', className)}
        onMouseEnter={(e) => {
          setIsHovered(true)
          onMouseEnterProp?.(e)
        }}
        onMouseLeave={(e) => {
          setIsHovered(false)
          onMouseLeaveProp?.(e)
        }}
        style={style}
        {...props}
      >
        <span
          aria-hidden="true"
          className="pointer-events-none invisible absolute inset-0"
          style={{
            fontVariationSettings: `"wght" ${activeWeight}`,
          }}
        >
          {children}
        </span>
        <span
          className="relative"
          style={{
            fontVariationSettings: `"wght" ${currentWeight}`,
            transition: reduceMotion
              ? 'none'
              : `font-variation-settings ${duration} var(--motion-ease-out)`,
          }}
        >
          {children}
        </span>
      </span>
    )
  },
)
WeightShiftText.displayName = 'WeightShiftText'

export function WeightShiftTextPreview() {
  return (
    <div
      className="w-full h-full min-h-50 rounded-lg overflow-hidden flex flex-col items-center justify-center gap-6 p-4"
      style={{ backgroundColor: 'var(--color-surface)' }}
    >
      <WeightShiftText
        baseWeight={300}
        activeWeight={700}
        className="text-lg cursor-pointer select-none"
        style={{ color: 'var(--color-fg)' }}
      >
        Hover to shift weight
      </WeightShiftText>
      <WeightShiftText
        baseWeight={400}
        activeWeight={600}
        active={true}
        className="text-sm"
        style={{ color: 'var(--color-muted)' }}
      >
        Always active
      </WeightShiftText>
    </div>
  )
}

'use client'

import { useRef, useState, useCallback, useEffect, type RefObject } from 'react'
import {
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  type MotionValue,
  type MotionStyle,
} from 'motion/react'
import { springs } from '@/lib/motion-tokens'

export interface ItemRect {
  top: number
  height: number
  left: number
  width: number
}

interface UseProximityHighlightOptions {
  axis?: 'x' | 'y'
  spring?: { stiffness: number; damping: number; mass: number }
}

interface UseProximityHighlightReturn {
  activeIndex: number | null
  setActiveIndex: (index: number | null) => void
  itemRects: ItemRect[]
  sessionRef: RefObject<number>
  handlers: {
    onMouseMove: (e: React.MouseEvent) => void
    onMouseEnter: () => void
    onMouseLeave: () => void
  }
  registerItem: (index: number, element: HTMLElement | null) => void
  measureItems: () => void
  highlightX: ReturnType<typeof useSpring>
  highlightSize: MotionValue<number>
  highlightOpacity: ReturnType<typeof useSpring>
  axis: 'x' | 'y'
}

export function useProximityHighlight<T extends HTMLElement>(
  containerRef: RefObject<T | null>,
  options: UseProximityHighlightOptions = {},
): UseProximityHighlightReturn {
  const { axis = 'y', spring: springConfig } = options
  const reduceMotion = useReducedMotion()

  const itemsRef = useRef(new Map<number, HTMLElement>())
  const [activeIndex, setActiveIndexRaw] = useState<number | null>(null)
  const activeIndexRef = useRef<number | null>(null)
  const [itemRects, setItemRects] = useState<ItemRect[]>([])
  const itemRectsRef = useRef<ItemRect[]>([])
  const sessionRef = useRef(0)
  const rafIdRef = useRef<number | null>(null)
  const remeasureRafIdRef = useRef<number | null>(null)
  const updateHighlightRef = useRef<(index: number | null) => void>(() => {})

  const rawX = useMotionValue(0)
  const highlightSize = useMotionValue(0)
  const rawOpacity = useMotionValue(0)

  const springOpts = reduceMotion ? { duration: 0 } : (springConfig ?? springs.settle)

  const highlightX = useSpring(rawX, springOpts)
  const highlightOpacity = useSpring(rawOpacity, springOpts)

  const measureItems = useCallback(() => {
    const container = containerRef.current
    if (!container) return
    const rects: ItemRect[] = []
    itemsRef.current.forEach((element, index) => {
      rects[index] = {
        top: element.offsetTop,
        height: element.offsetHeight,
        left: element.offsetLeft,
        width: element.offsetWidth,
      }
    })
    itemRectsRef.current = rects
    setItemRects(rects)
  }, [containerRef])

  const registerItem = useCallback(
    (index: number, element: HTMLElement | null) => {
      if (element) {
        itemsRef.current.set(index, element)
      } else {
        itemsRef.current.delete(index)
      }
      if (remeasureRafIdRef.current !== null) {
        cancelAnimationFrame(remeasureRafIdRef.current)
      }
      remeasureRafIdRef.current = requestAnimationFrame(() => {
        remeasureRafIdRef.current = null
        measureItems()
      })
    },
    [measureItems],
  )

  const updateHighlight = useCallback(
    (index: number | null) => {
      if (index === null || !itemRectsRef.current[index]) {
        if (reduceMotion) {
          rawOpacity.jump(0)
        } else {
          rawOpacity.set(0)
        }
        return
      }
      const r = itemRectsRef.current[index]
      if (axis === 'y') {
        if (reduceMotion) {
          rawX.jump(r.top)
          highlightSize.jump(r.height)
          rawOpacity.jump(1)
        } else {
          rawX.set(r.top)
          highlightSize.jump(r.height)
          rawOpacity.set(1)
        }
      } else {
        if (reduceMotion) {
          rawX.jump(r.left)
          highlightSize.jump(r.width)
          rawOpacity.jump(1)
        } else {
          rawX.set(r.left)
          highlightSize.jump(r.width)
          rawOpacity.set(1)
        }
      }
    },
    [axis, reduceMotion, rawX, highlightSize, rawOpacity],
  )

  useEffect(() => {
    updateHighlightRef.current = updateHighlight
  })

  const setActiveIndex = useCallback((index: number | null) => {
    setActiveIndexRaw(index)
    updateHighlightRef.current(index)
  }, [])

  const handleMouseMove = useCallback(
    (e: React.MouseEvent) => {
      const mouseX = e.clientX
      const mouseY = e.clientY

      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current)
      }

      rafIdRef.current = requestAnimationFrame(() => {
        rafIdRef.current = null
        const container = containerRef.current
        if (!container) return

        const containerRect = container.getBoundingClientRect()
        const mousePos = axis === 'x' ? mouseX : mouseY

        let closestIndex: number | null = null
        let closestDistance = Infinity
        let containingIndex: number | null = null

        const rects = itemRectsRef.current
        const scrollOffset = axis === 'x' ? container.scrollLeft : container.scrollTop
        const borderOffset = axis === 'x' ? container.clientLeft : container.clientTop
        const containerEdge = axis === 'x' ? containerRect.left : containerRect.top

        const layoutSize = axis === 'x' ? container.offsetWidth : container.offsetHeight
        const visualSize = axis === 'x' ? containerRect.width : containerRect.height
        const scale = layoutSize > 0 ? visualSize / layoutSize : 1

        for (let index = 0; index < rects.length; index++) {
          const r = rects[index]
          if (!r) continue

          const contentPos = axis === 'x' ? r.left : r.top
          const itemStart = containerEdge + (borderOffset + contentPos - scrollOffset) * scale
          const itemSize = (axis === 'x' ? r.width : r.height) * scale
          const itemEnd = itemStart + itemSize

          if (mousePos >= itemStart && mousePos <= itemEnd) {
            containingIndex = index
          }

          const itemCenter = itemStart + itemSize / 2
          const distance = Math.abs(mousePos - itemCenter)

          if (distance < closestDistance) {
            closestDistance = distance
            closestIndex = index
          }
        }

        const next = containingIndex ?? closestIndex
        if (next !== activeIndexRef.current) {
          activeIndexRef.current = next
          setActiveIndex(next)
        }
      })
    },
    [axis, containerRef, setActiveIndex],
  )

  const handleMouseEnter = useCallback(() => {
    sessionRef.current += 1
  }, [])

  const handleMouseLeave = useCallback(() => {
    if (rafIdRef.current !== null) {
      cancelAnimationFrame(rafIdRef.current)
      rafIdRef.current = null
    }
    activeIndexRef.current = null
    setActiveIndex(null)
  }, [setActiveIndex])

  useEffect(() => {
    return () => {
      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current)
      }
      if (remeasureRafIdRef.current !== null) {
        cancelAnimationFrame(remeasureRafIdRef.current)
      }
    }
  }, [])

  return {
    activeIndex,
    setActiveIndex,
    itemRects,
    sessionRef,
    handlers: {
      onMouseMove: handleMouseMove,
      onMouseEnter: handleMouseEnter,
      onMouseLeave: handleMouseLeave,
    },
    registerItem,
    measureItems,
    highlightX,
    highlightSize,
    highlightOpacity,
    axis,
  }
}

export interface ProximityHighlightProps {
  highlightX: ReturnType<typeof useSpring>
  highlightSize: MotionValue<number>
  highlightOpacity: ReturnType<typeof useSpring>
  axis: 'x' | 'y'
  className?: string
  style?: MotionStyle
}

export function ProximityHighlight({
  highlightX,
  highlightSize,
  highlightOpacity,
  axis,
  className,
  style,
}: ProximityHighlightProps) {
  return (
    <motion.div
      aria-hidden="true"
      className={className}
      style={{
        ...style,
        position: 'absolute',
        inset: 0,
        pointerEvents: 'none',
        ...(axis === 'y'
          ? { y: highlightX, height: highlightSize }
          : { x: highlightX, width: highlightSize }),
        opacity: highlightOpacity,
      }}
    />
  )
}

export function useRegisterProximityItem(
  registerItem: (index: number, element: HTMLElement | null) => void,
  index: number,
  ref: RefObject<HTMLElement | null>,
) {
  useEffect(() => {
    registerItem(index, ref.current)
    return () => registerItem(index, null)
  }, [index, registerItem, ref])
}

export const durations = {
  instant: '50ms',
  fast: '120ms',
  base: '200ms',
  slow: '320ms',
} as const

export const easings = {
  out: 'cubic-bezier(0.22, 1, 0.36, 1)',
  inOut: 'cubic-bezier(0.65, 0, 0.35, 1)',
} as const

export const springs = {
  fast: { type: 'spring', stiffness: 400, damping: 30, mass: 0.8 },
  press: { type: 'spring', stiffness: 700, damping: 32, mass: 1 },
  moderate: { type: 'spring', stiffness: 300, damping: 24, mass: 1 },
  settle: { type: 'spring', stiffness: 260, damping: 26, mass: 1 },
} as const
